-- Migration 446: AA-1126 (S283) — the gateway's spend controls per environment: the connection cap mode (G1), the
-- anomaly breaker (G2) and the hard cap per run of waves, ad-hoc and eval runs (G4), in the platform settings registry
-- (CIS 407; tech lead S279: a threshold, limit, cap or policy value is a setting on Platform › Settings), plus the
-- breaker's reset columns on the app profile.
--
-- Why. Tech lead policy S283 (root docs/audits/2026-11-17-S283-session/ai-caps-gap.md): Dev keeps hard caps on the AI
-- connections; prod is pay per use, where a connection cap alerts and fails over but never blocks a customer, only an
-- anomaly breaker (today's spend above a multiple of the normal day) may stop calls, and internal batch runs keep a
-- hard cap per run. One code path: each environment's settings registry picks the behaviour, so going to prod is a
-- settings change. Every default below is today's Dev behaviour (hard stop, no refusal by the breaker).
--
-- What:
--   1. Eight rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py
--      into shared/settings/compiled_defaults.json in this PR), area "spend", scope platform, maker-checker, no
--      evidence, no env override, enforced (shared/llm_client/caps_settings.py names every key, the settings-lint reader
--      check; the gateway reads them in the code PR):
--        cis.llm.connection_cap_mode       enum hard_stop | failover_continue, default hard_stop       (impact high)
--        cis.llm.anomaly_breaker_mode      enum off | alert | enforce, default alert                  (impact high)
--        cis.llm.anomaly_multiple          numeric x 1.5-100, default 4                                 (impact high)
--        cis.llm.anomaly_floor_usd         usd 0-10000, default 25                                     (impact high)
--        cis.llm.anomaly_baseline_days     int days 7-60, default 14                                  (impact medium)
--        cis.spend.run_cap_s1_rewrite_usd  usd 0.05-20, default 2   (one S1 rewrite job, a wave tour)  (impact high)
--        cis.spend.run_cap_eval_usd        usd 0.05-50, default 10  (= the R2 run cap)                  (impact high)
--        cis.spend.run_cap_adhoc_usd       usd 0.05-50, default 5                                      (impact high)
--      Starting values: an S1 rewrite costs about 0.05-0.3 USD per tour (session logs), 2 USD leaves room for the
--      writer's three internal attempts; the breaker floor keeps quiet days (a few USD) from tripping on noise. Each
--      seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. shared.llm_app_profile gains anomaly_reset_at (timestamptz) and anomaly_reset_by (text, <= 128 chars): the last
--      admin reset of the app's anomaly breaker (POST /admin/ai-gateway/anomaly-breaker/{app}/reset, audited). After a
--      reset the breaker counts the app's spend from that moment, so a reset gives the rest of the UTC day a fresh
--      allowance. cis_app may UPDATE the two columns (the table's other grants unchanged, CIS 345).
--   3. Register 446.
--
-- Behaviour on apply. None for running code: no value row is seeded, nothing on main reads these keys or columns, and
-- the defaults equal today's behaviour. After the code PR: connection caps still hard stop; the breaker alerts only.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table
-- and an ALTER TABLE with a grant. MIG-4: a migration-only PR, applied on Dev by Infra Migration Apply when the job
-- tables are idle (ADR 0017a), then the code PR (no readiness raise: the code reads the keys through
-- shared/llm_client/caps_settings.py, which keeps today's behaviour for a key not seeded yet, and the to_jsonb read of
-- the app profile has no new column before this file). DM-6.1: anomaly_reset_by holds a staff actor id, like
-- updated_by. DM-7.1: no new table.
--
-- Number. 445 (AA-1125, applied 17/11/2026) is the newest CIS migration on main: 446 is the owner main max + 1. If
-- it differs at merge, renumber (git grep '446_' and '446' here, in tests/integration/test_aa1126_migration_446.py,
-- compiled_defaults.json and docs/implementation-notes/AA-1126.md).
--
-- Locks. One INSERT of eight rows (the definition guard trigger allows the file's role, cis_owner); ALTER TABLE ADD
-- COLUMN with no default on a 4-row table (metadata only). lock_timeout 5s.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the keys' value rows first, then the keys;
-- ALTER TABLE shared.llm_app_profile DROP COLUMN anomaly_reset_at, DROP COLUMN anomaly_reset_by (a destructive file).

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.llm.connection_cap_mode", "app": "cis", "area": "spend", "label": "AI connections: what a monthly cap does", "description": "How the AI gateway (shared/llm_client/connection_budget.py) treats a connection that reached its monthly budget (AI gateway > Providers > Connections). hard_stop: the connection is left out of every route and a call with no other way in stops as a budget stop (the Dev rule). failover_continue: it is still left out while another connection or route model can answer; when every one is over its cap the call goes on (caps lifted for that call) and one alert per day is raised, so a customer is never blocked by a connection cap (the prod rule). A connection whose own cost policy is alert only stays alert only. Each environment sets its own value.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["hard_stop", "failover_continue"], "default_value": "hard_stop", "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "What happens when an AI connection (an AWS account or a vendor API key) reaches its monthly budget: stop using it, or fail over and keep serving.", "raise": "failover_continue: calls fail over to the next connection and, when every connection is over its cap, still go on with an alert. Spend can pass the connection budgets.", "lower": "hard_stop: a connection over its budget is never called; a job with no other way in stops as a budget stop and waits.", "when": "Keep hard_stop on Dev to avoid over-testing. Use failover_continue in prod, where customers pay per use and must not be blocked by a platform cap.", "example": "With the default hard_stop, a job whose every connection is at 100 % of its budget stops. With failover_continue the call goes to the next connection, and if all are at 100 % it still goes to the first healthy one and the admin bell says so."}, "vi": {"what": "Điều gì xảy ra khi một kết nối AI (một tài khoản AWS hay một khoá API của nhà cung cấp) chạm ngân sách tháng: ngừng dùng, hay chuyển sang kết nối khác và vẫn phục vụ.", "raise": "failover_continue: lệnh gọi chuyển sang kết nối kế tiếp và, khi mọi kết nối đều vượt trần, vẫn chạy tiếp kèm cảnh báo. Chi tiêu có thể vượt ngân sách kết nối.", "lower": "hard_stop: kết nối vượt ngân sách không bao giờ được gọi; job không còn đường nào khác sẽ dừng vì ngân sách và chờ.", "when": "Giữ hard_stop ở Dev để tránh test quá tay. Dùng failover_continue ở prod, nơi khách trả theo mức dùng và không được bị chặn bởi trần của nền tảng.", "example": "Với mặc định hard_stop, job mà mọi kết nối đều ở 100 % ngân sách sẽ dừng. Với failover_continue lệnh gọi sang kết nối kế, và nếu tất cả đều 100 % thì vẫn tới kết nối khoẻ đầu tiên và chuông admin báo việc đó."}}},
{"key": "cis.llm.anomaly_breaker_mode", "app": "cis", "area": "spend", "label": "AI anomaly breaker: mode", "description": "The AI gateway's anomaly breaker (shared/llm_client/anomaly_breaker.py) compares an app's AI spend today (UTC, or since its last reset) with a multiple of its median daily spend over the last days. off: not checked. alert: when tripped, one admin bell and one ops e-mail per app and day; nothing is refused. enforce: when tripped, the app's new AI calls are refused (budget stop) until an administrator resets the breaker (AI gateway > Budgets > Spend controls) or the UTC day ends. Each environment sets its own value.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["off", "alert", "enforce"], "default_value": "alert", "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "Whether an unusual jump in an app's AI spend today only raises an alert, or also stops that app's new AI calls.", "raise": "enforce: a runaway loop or abuse is stopped within a minute of crossing the threshold; real work of that app also waits until someone resets the breaker.", "lower": "alert or off: nothing is ever refused by the breaker; you rely on the alert (or nothing) to notice a runaway spend.", "when": "Use enforce in prod, where it is the only control allowed to stop customer AI calls. Keep alert on Dev, where waves make big days normal.", "example": "With the default alert, a multiple of 4 and a median day of 10 USD, a day above 40 USD rings the bell once; with enforce, the app's calls are also refused until an admin presses Reset."}, "vi": {"what": "Khi chi tiêu AI hôm nay của một app tăng bất thường thì chỉ cảnh báo, hay dừng luôn các lệnh gọi AI mới của app đó.", "raise": "enforce: một vòng lặp chạy mất kiểm soát hay bị lạm dụng sẽ bị chặn trong vòng một phút sau khi vượt ngưỡng; việc thật của app đó cũng phải chờ tới khi có người reset.", "lower": "alert hoặc off: breaker không bao giờ từ chối lệnh gọi nào; chỉ dựa vào cảnh báo (hoặc không gì cả) để phát hiện chi tiêu mất kiểm soát.", "when": "Dùng enforce ở prod, nơi đây là cơ chế duy nhất được phép dừng lệnh gọi AI của khách. Giữ alert ở Dev, nơi các wave làm ngày chi nhiều là chuyện bình thường.", "example": "Với mặc định alert, bội số 4 và ngày trung vị 10 USD, một ngày vượt 40 USD làm chuông kêu một lần; với enforce, lệnh gọi của app còn bị từ chối tới khi admin bấm Reset."}}},
{"key": "cis.llm.anomaly_multiple", "app": "cis", "area": "spend", "label": "AI anomaly breaker: multiple of a normal day", "description": "The anomaly breaker trips when an app's AI spend today is above this multiple of its median daily spend over the baseline days (and above the floor). Read by shared/llm_client/anomaly_breaker.py.", "value_type": "numeric", "unit": "x", "min_value": 1.5, "max_value": 100, "allowed_values": null, "default_value": 4, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "How many normal days of AI spend an app may use in one day before the anomaly breaker trips.", "raise": "Busier days pass without a trip; a runaway spend runs longer before it is caught.", "lower": "A runaway spend is caught sooner; an honest busy day (a launch, a big import) trips it more often.", "when": "Lower it once daily spend is steady; raise it before a planned busy day, or reset the breaker that day.", "example": "With 4 and a median day of 10 USD, the breaker trips above 40 USD today (if that is above the floor)."}, "vi": {"what": "Một app được tiêu bao nhiêu lần chi tiêu AI của một ngày bình thường trong một ngày trước khi breaker bất thường ngắt.", "raise": "Ngày bận hơn vẫn qua mà không ngắt; chi tiêu mất kiểm soát chạy lâu hơn mới bị bắt.", "lower": "Chi tiêu mất kiểm soát bị bắt sớm hơn; một ngày bận thật (ra mắt, nhập lớn) dễ làm ngắt hơn.", "when": "Giảm khi chi tiêu ngày đã ổn định; tăng trước một ngày bận đã lên kế hoạch, hoặc reset breaker hôm đó.", "example": "Với 4 và ngày trung vị 10 USD, breaker ngắt khi hôm nay vượt 40 USD (nếu số đó cao hơn mức sàn)."}}},
{"key": "cis.llm.anomaly_floor_usd", "app": "cis", "area": "spend", "label": "AI anomaly breaker: spend floor", "description": "The anomaly breaker never trips while an app's AI spend today is at or below this many USD, whatever its median day is (an app with little or no history would otherwise trip on its first busy hour). Read by shared/llm_client/anomaly_breaker.py.", "value_type": "usd", "unit": "USD/day", "min_value": 0, "max_value": 10000, "allowed_values": null, "default_value": 25, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "The AI spend of one app in one day under which the anomaly breaker never trips.", "raise": "Small apps and quiet days never trip; a runaway spend on a quiet app runs up to this amount first.", "lower": "A runaway spend on a quiet app is caught sooner; a normal busy hour may trip it.", "when": "Set it a little above the busiest normal day of the smallest app.", "example": "With 25 USD, an app whose median day is 1 USD trips only once today's spend passes 25 USD."}, "vi": {"what": "Chi tiêu AI trong một ngày của một app mà dưới mức đó breaker bất thường không bao giờ ngắt.", "raise": "App nhỏ và ngày vắng không bao giờ ngắt; chi tiêu mất kiểm soát trên app vắng chạy tới mức này trước.", "lower": "Chi tiêu mất kiểm soát trên app vắng bị bắt sớm hơn; một giờ bận bình thường có thể làm ngắt.", "when": "Đặt cao hơn một chút so với ngày bận bình thường nhất của app nhỏ nhất.", "example": "Với 25 USD, một app có ngày trung vị 1 USD chỉ ngắt khi chi tiêu hôm nay vượt 25 USD."}}},
{"key": "cis.llm.anomaly_baseline_days", "app": "cis", "area": "spend", "label": "AI anomaly breaker: days in the normal-day baseline", "description": "The anomaly breaker's normal day is the median of an app's daily AI spend over this many UTC days before today (days with no spend count as 0). Read by shared/llm_client/anomaly_breaker.py.", "value_type": "int", "unit": "days", "min_value": 7, "max_value": 60, "allowed_values": null, "default_value": 14, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "How many past days make up an app's normal day of AI spend (their median).", "raise": "The normal day moves slowly: a lasting rise in use takes longer to stop tripping the breaker.", "lower": "The normal day follows recent use quickly; a few busy days in a row raise the threshold fast.", "when": "Keep two weeks; shorten it while a new app is still growing quickly.", "example": "With 14, the normal day is the median of the last 14 days before today."}, "vi": {"what": "Bao nhiêu ngày gần nhất tạo nên ngày chi tiêu AI bình thường của một app (lấy trung vị).", "raise": "Ngày bình thường thay đổi chậm: mức dùng tăng lâu dài phải chờ lâu hơn mới hết làm ngắt breaker.", "lower": "Ngày bình thường theo sát mức dùng gần đây; vài ngày bận liên tiếp làm ngưỡng tăng nhanh.", "when": "Giữ hai tuần; rút ngắn khi một app mới còn đang tăng nhanh.", "example": "Với 14, ngày bình thường là trung vị của 14 ngày trước hôm nay."}}},
{"key": "cis.spend.run_cap_s1_rewrite_usd", "app": "cis", "area": "spend", "label": "Tour rewrite in a wave: hard cap per run", "description": "The most one S1 rewrite job (one tour of a rerun wave) may spend on AI calls, from the ledger (shared.llm_call_log rows of the job, every attempt). The job payload's cap_usd wins when it carries one; new jobs carry this value from when they were queued. At the cap the gateway refuses the job's next call and the job stops as stopped_budget. Read by shared/llm_client/run_cap.py.", "value_type": "usd", "unit": "USD/run", "min_value": 0.05, "max_value": 20, "allowed_values": null, "default_value": 2, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "The most AI money one tour rewrite (one job of a rerun wave) may spend before it is stopped.", "raise": "A tour whose writer retries a lot can finish; a stuck tour costs more before it stops.", "lower": "A stuck tour is stopped sooner; a long tour with honest retries may stop before it is written.", "when": "Keep it a few times the usual cost per tour; lower it for a trial wave.", "example": "With 2 USD, a tour whose calls have cost 2 USD gets no further call and its job ends as stopped by budget."}, "vi": {"what": "Số tiền AI tối đa một lần viết lại một tour (một job của wave chạy lại) được tiêu trước khi bị dừng.", "raise": "Tour có writer phải thử lại nhiều vẫn xong được; tour bị kẹt tốn nhiều hơn trước khi dừng.", "lower": "Tour bị kẹt dừng sớm hơn; tour dài có lượt thử lại chính đáng có thể dừng trước khi viết xong.", "when": "Giữ ở mức vài lần chi phí thường của một tour; giảm khi chạy wave thử.", "example": "Với 2 USD, một tour đã tiêu 2 USD cho lệnh gọi sẽ không được gọi thêm và job kết thúc vì ngân sách."}}},
{"key": "cis.spend.run_cap_eval_usd", "app": "cis", "area": "spend", "label": "Eval runs: hard cap per run", "description": "The most one eval run may spend on AI calls (a run bound with an eval label, or the job it runs in), from the ledger. The job payload's cap_usd wins when it carries one (the W5 proofs and writing-memory R2 jobs do). At the cap the gateway refuses the run's next call (a budget stop). Read by shared/llm_client/run_cap.py.", "value_type": "usd", "unit": "USD/run", "min_value": 0.05, "max_value": 50, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "The most AI money one evaluation run may spend when it does not state its own cap.", "raise": "Bigger eval sets finish in one run; a mistaken run costs more before it stops.", "lower": "A mistaken run stops sooner; a large eval set must be split into several runs.", "when": "Keep it near the largest eval you approve; a run that states its own cap is not affected.", "example": "With 10 USD, an eval run with no cap of its own stops once its calls have cost 10 USD."}, "vi": {"what": "Số tiền AI tối đa một lần chạy đánh giá (eval) được tiêu khi lần chạy đó không tự ghi trần riêng.", "raise": "Bộ eval lớn hơn chạy xong trong một lần; lần chạy nhầm tốn nhiều hơn trước khi dừng.", "lower": "Lần chạy nhầm dừng sớm hơn; bộ eval lớn phải chia thành nhiều lần chạy.", "when": "Giữ gần mức eval lớn nhất bạn duyệt; lần chạy có trần riêng không bị ảnh hưởng.", "example": "Với 10 USD, một lần eval không có trần riêng sẽ dừng khi lệnh gọi đã tốn 10 USD."}}},
{"key": "cis.spend.run_cap_adhoc_usd", "app": "cis", "area": "spend", "label": "Ad-hoc runs: hard cap per run", "description": "The most one ad-hoc run (a call whose stage starts with adhoc_) may spend on AI calls, from the ledger: the job's rows when it runs in a job, else the rows of its stage since its process started. The job payload's cap_usd wins when it carries one. At the cap the gateway refuses the run's next call (a budget stop). Read by shared/llm_client/run_cap.py.", "value_type": "usd", "unit": "USD/run", "min_value": 0.05, "max_value": 50, "allowed_values": null, "default_value": 5, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": true, "guide": {"en": {"what": "The most AI money one ad-hoc script run (an A/B test, a backfill, a one-off check) may spend.", "raise": "Bigger one-off runs finish without splitting; a script with a bug costs more before it stops.", "lower": "A script with a bug stops sooner; a big approved run must be split or given its own cap in a job.", "when": "Keep it near the largest one-off run you approve without a job; raise it for the day of a bigger approved run.", "example": "With 5 USD, an A/B script whose calls have cost 5 USD gets no further call."}, "vi": {"what": "Số tiền AI tối đa một lần chạy script adhoc (A/B, backfill, kiểm tra một lần) được tiêu.", "raise": "Lần chạy một lần lớn hơn xong mà không phải chia; script có lỗi tốn nhiều hơn trước khi dừng.", "lower": "Script có lỗi dừng sớm hơn; lần chạy lớn đã duyệt phải chia nhỏ hoặc chạy trong job có trần riêng.", "when": "Giữ gần mức lần chạy một lần lớn nhất bạn duyệt không qua job; tăng trong ngày có lần chạy lớn đã duyệt.", "example": "Với 5 USD, một script A/B đã tốn 5 USD cho lệnh gọi sẽ không được gọi thêm."}}}
]
$seed$::jsonb) AS s (key text, app text, area text, label text, description text, value_type text, unit text,
                      min_value numeric, max_value numeric, allowed_values jsonb, default_value jsonb, scope_kind text,
                      impact text, approval text, evidence_required boolean, env_override text, cache_s integer,
                      enforced boolean, guide jsonb)
ON CONFLICT (key) DO NOTHING;
-- settings-seed:end

ALTER TABLE shared.llm_app_profile
    ADD COLUMN IF NOT EXISTS anomaly_reset_at timestamptz,
    ADD COLUMN IF NOT EXISTS anomaly_reset_by text;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'llm_app_profile_anomaly_reset_by_check') THEN
        ALTER TABLE shared.llm_app_profile
            ADD CONSTRAINT llm_app_profile_anomaly_reset_by_check
            CHECK (anomaly_reset_by IS NULL OR length(anomaly_reset_by) <= 128);
    END IF;
END $$;

COMMENT ON COLUMN shared.llm_app_profile.anomaly_reset_at IS
    'AA-1126 G2 (CIS 446): the last admin reset of the app''s AI anomaly breaker (shared/llm_client/anomaly_breaker.py); '
    'the breaker counts the app''s spend today from max(UTC midnight, this time). NULL = never reset.';
COMMENT ON COLUMN shared.llm_app_profile.anomaly_reset_by IS
    'AA-1126 G2 (CIS 446): the staff actor of the last anomaly breaker reset (audited in acp_shared.audit_log).';

GRANT UPDATE (anomaly_reset_at, anomaly_reset_by) ON shared.llm_app_profile TO cis_app;

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('446', now(), 'AA-1126: gateway spend controls per environment (connection cap mode, anomaly breaker, run '
                      'caps) in the settings registry; anomaly breaker reset columns on shared.llm_app_profile')
ON CONFLICT (version) DO NOTHING;

COMMIT;
